parameters.jsCode:
// Junta la candidatura con la extraccion, sin fiarse de que venga limpia.
const salida = [];
for (const item of $input.all()) {
  const cand = $('Normalizar candidatura').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let datos;
  try {
    datos = JSON.parse(bruto);
  } catch (error) {
    datos = { puestos: [], anios_experiencia_declarados: null, formacion: [], permisos_certificados: [], idiomas: [], disponibilidad: '', dudas: ['extraccion no parseable: ' + bruto.slice(0, 150) + ' - revisar el CV a mano'] };
  }
  salida.push({
    json: {
      ...cand,
      datos_extraidos: JSON.stringify(datos),
      dudas_extraccion: (datos.dudas || []).join(' | '),
      extraccion_revisada: 'false',
      estado: 'extraida',
    },
  });
}
return salida;

